CREATE VIEW archive_x_published_media AS
            SELECT m.*
            FROM media m
            JOIN resource_state rs ON rs.media_id=m.id
            WHERE rs.catalogue_state='COMPLETE'
              AND COALESCE(m.status,'')<>'SOURCE_DELETED'
              AND rs.metadata_state='COMPLETE'
              AND rs.entity_state='COMPLETE'
              AND rs.snapshot_state='READY'
              AND EXISTS (
                  SELECT 1 FROM timeline_preview_cache tpc
                  WHERE tpc.source_channel=CAST(m.source_channel AS TEXT)
                    AND tpc.video_message_id=m.source_message_id
                    AND UPPER(COALESCE(tpc.status,''))='READY'
                    AND CAST(COALESCE(tpc.frame_count,0) AS INTEGER)=36
              )
              AND EXISTS (
                  SELECT 1 FROM thumbnail_cache tc
                  WHERE tc.source_channel=CAST(m.source_channel AS TEXT)
                    AND tc.video_message_id=m.source_message_id
                    AND tc.source='playback-snapshot'
                    AND tc.data IS NOT NULL AND length(tc.data)>0
              )
              AND COALESCE(m.streamable,0)=1
              -- Only a real Telegram peer may be a Library-facing video.
              -- Synthetic Content Automation / Local Upload staging identities
              -- can satisfy readiness internally, but must never appear as a
              -- duplicate card before the verified destination message exists.
              AND (CAST(m.source_channel AS TEXT) GLOB '-[0-9]*'
                   OR (CAST(m.source_channel AS TEXT)<>'' AND CAST(m.source_channel AS TEXT) NOT GLOB '*[^0-9]*'))
              AND (
                  -- V29.4.129: two indexed lookups instead of one OR'ed
                  -- condition. The OR made SQLite walk every READY asset for
                  -- every video (performer page: 10 s; Library slow).
                  EXISTS (SELECT 1 FROM asset_registry ar
                          WHERE ar.entity_type='telegram_video'
                            AND ar.entity_id=(CAST(m.source_channel AS TEXT) || ':' || CAST(m.source_message_id AS TEXT))
                            AND ar.asset_type='PLAYBACK_REPRESENTATIVE'
                            AND ar.state='READY')
                  OR EXISTS (SELECT 1 FROM asset_registry ar
                             WHERE ar.media_id=m.id
                               AND ar.asset_type='PLAYBACK_REPRESENTATIVE'
                               AND ar.state='READY')
              );

CREATE VIEW archive_x_catalogued_media AS
            SELECT m.*,
                   COALESCE(rs.catalogue_state,'PENDING') AS library_catalogue_state,
                   COALESCE(rs.metadata_state,'PENDING') AS library_metadata_state,
                   COALESCE(rs.entity_state,'PENDING') AS library_entity_state,
                   COALESCE(rs.snapshot_state,'PENDING') AS library_snapshot_state,
                   CASE WHEN COALESCE(rs.snapshot_state,'PENDING')='READY'
                          AND EXISTS (
                              SELECT 1 FROM timeline_preview_cache tpc
                              WHERE tpc.source_channel=CAST(m.source_channel AS TEXT)
                                AND tpc.video_message_id=m.source_message_id
                                AND UPPER(COALESCE(tpc.status,''))='READY'
                                AND CAST(COALESCE(tpc.frame_count,0) AS INTEGER)=36
                          )
                          AND EXISTS (
                              SELECT 1 FROM thumbnail_cache tc
                              WHERE tc.source_channel=CAST(m.source_channel AS TEXT)
                                AND tc.video_message_id=m.source_message_id
                                AND tc.source='playback-snapshot'
                                AND tc.data IS NOT NULL AND length(tc.data)>0
                          )
                          AND COALESCE(m.streamable,0)=1
                          AND (
                              EXISTS (SELECT 1 FROM asset_registry ar
                                      WHERE ar.entity_type='telegram_video'
                                        AND ar.entity_id=(CAST(m.source_channel AS TEXT) || ':' || CAST(m.source_message_id AS TEXT))
                                        AND ar.asset_type='PLAYBACK_REPRESENTATIVE'
                                        AND ar.state='READY')
                              OR EXISTS (SELECT 1 FROM asset_registry ar
                                         WHERE ar.media_id=m.id
                                           AND ar.asset_type='PLAYBACK_REPRESENTATIVE'
                                           AND ar.state='READY')
                          )
                        THEN 1 ELSE 0 END AS library_ready,
                   CASE
                     WHEN COALESCE(rs.snapshot_state,'PENDING')<>'READY'
                       OR NOT EXISTS (
                           SELECT 1 FROM timeline_preview_cache tpc
                           WHERE tpc.source_channel=CAST(m.source_channel AS TEXT)
                             AND tpc.video_message_id=m.source_message_id
                             AND UPPER(COALESCE(tpc.status,''))='READY'
                             AND CAST(COALESCE(tpc.frame_count,0) AS INTEGER)=36
                       ) THEN 'Snapshots pending'
                     WHEN NOT EXISTS (SELECT 1 FROM thumbnail_cache tc
                         WHERE tc.source_channel=CAST(m.source_channel AS TEXT)
                           AND tc.video_message_id=m.source_message_id
                           AND tc.source='playback-snapshot'
                           AND tc.data IS NOT NULL AND length(tc.data)>0)
                       OR (NOT EXISTS (SELECT 1 FROM asset_registry ar WHERE ar.entity_type='telegram_video'
                         AND ar.entity_id=(CAST(m.source_channel AS TEXT) || ':' || CAST(m.source_message_id AS TEXT))
                         AND ar.asset_type='PLAYBACK_REPRESENTATIVE' AND ar.state='READY')
                       AND NOT EXISTS (SELECT 1 FROM asset_registry ar WHERE ar.media_id=m.id
                          AND ar.asset_type='PLAYBACK_REPRESENTATIVE' AND ar.state='READY')) THEN 'Representative image pending'
                     WHEN COALESCE(m.streamable,0)<>1 THEN 'Not streamable'
                     ELSE 'Ready'
                   END AS library_state
            FROM media m
            LEFT JOIN resource_state rs ON rs.media_id=m.id
            WHERE COALESCE(m.status,'')<>'SOURCE_DELETED'
              AND COALESCE(m.source_message_id,0)>0
              AND (CAST(m.source_channel AS TEXT) GLOB '-[0-9]*'
                   OR (CAST(m.source_channel AS TEXT)<>'' AND CAST(m.source_channel AS TEXT) NOT GLOB '*[^0-9]*'));

CREATE VIEW archive_x_library_media_exact AS
            SELECT cm.*
            FROM archive_x_catalogued_media cm
            WHERE
              -- Only publish a video into the Library after its validated 36-frame
              -- set, representative image, and streamability are all ready. The
              -- underlying archive_x_catalogued_media view remains unrestricted so
              -- snapshot preparation can still discover and repair pending videos.
              cm.library_ready=1
              -- A split group is invisible until every part and its preview are verified.
              AND NOT EXISTS (
                  SELECT 1 FROM split_file_groups sg
                  WHERE sg.destination_channel=CAST(cm.source_channel AS TEXT)
                    AND sg.primary_message_id=cm.source_message_id
                    AND sg.status<>'VERIFIED'
              )
              -- Never expose the additional physical volume messages as separate cards.
              AND NOT EXISTS (
                  SELECT 1 FROM split_file_parts sp
                  JOIN split_file_groups sg ON sg.group_id=sp.group_id
                  WHERE sp.destination_channel=CAST(cm.source_channel AS TEXT)
                    AND sp.message_id=cm.source_message_id
                    AND (sg.status<>'VERIFIED' OR sp.message_id<>sg.primary_message_id)
              );

CREATE TABLE ax_library_ready (media_id INTEGER PRIMARY KEY);

CREATE TRIGGER ax_lr_resource_state_insert AFTER INSERT ON resource_state BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT NEW.media_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT NEW.media_id); END;

CREATE TRIGGER ax_lr_resource_state_update AFTER UPDATE ON resource_state BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT NEW.media_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT NEW.media_id); DELETE FROM ax_library_ready WHERE media_id IN (SELECT OLD.media_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT OLD.media_id); END;

CREATE TRIGGER ax_lr_resource_state_delete AFTER DELETE ON resource_state BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT OLD.media_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT OLD.media_id); END;

CREATE TRIGGER ax_lr_timeline_preview_cache_insert AFTER INSERT ON timeline_preview_cache BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT id FROM media WHERE source_channel=NEW.source_channel AND source_message_id=NEW.video_message_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT id FROM media WHERE source_channel=NEW.source_channel AND source_message_id=NEW.video_message_id); END;

CREATE TRIGGER ax_lr_timeline_preview_cache_update AFTER UPDATE ON timeline_preview_cache BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT id FROM media WHERE source_channel=NEW.source_channel AND source_message_id=NEW.video_message_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT id FROM media WHERE source_channel=NEW.source_channel AND source_message_id=NEW.video_message_id); DELETE FROM ax_library_ready WHERE media_id IN (SELECT id FROM media WHERE source_channel=OLD.source_channel AND source_message_id=OLD.video_message_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT id FROM media WHERE source_channel=OLD.source_channel AND source_message_id=OLD.video_message_id); END;

CREATE TRIGGER ax_lr_timeline_preview_cache_delete AFTER DELETE ON timeline_preview_cache BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT id FROM media WHERE source_channel=OLD.source_channel AND source_message_id=OLD.video_message_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT id FROM media WHERE source_channel=OLD.source_channel AND source_message_id=OLD.video_message_id); END;

CREATE TRIGGER ax_lr_thumbnail_cache_insert AFTER INSERT ON thumbnail_cache BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT id FROM media WHERE source_channel=NEW.source_channel AND source_message_id=NEW.video_message_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT id FROM media WHERE source_channel=NEW.source_channel AND source_message_id=NEW.video_message_id); END;

CREATE TRIGGER ax_lr_thumbnail_cache_update AFTER UPDATE ON thumbnail_cache BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT id FROM media WHERE source_channel=NEW.source_channel AND source_message_id=NEW.video_message_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT id FROM media WHERE source_channel=NEW.source_channel AND source_message_id=NEW.video_message_id); DELETE FROM ax_library_ready WHERE media_id IN (SELECT id FROM media WHERE source_channel=OLD.source_channel AND source_message_id=OLD.video_message_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT id FROM media WHERE source_channel=OLD.source_channel AND source_message_id=OLD.video_message_id); END;

CREATE TRIGGER ax_lr_thumbnail_cache_delete AFTER DELETE ON thumbnail_cache BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT id FROM media WHERE source_channel=OLD.source_channel AND source_message_id=OLD.video_message_id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT id FROM media WHERE source_channel=OLD.source_channel AND source_message_id=OLD.video_message_id); END;

CREATE TRIGGER ax_lr_asset_registry_insert AFTER INSERT ON asset_registry BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT NEW.media_id WHERE NEW.media_id IS NOT NULL UNION SELECT id FROM media WHERE NEW.entity_type='telegram_video' AND instr(NEW.entity_id,':')>0 AND source_channel=substr(NEW.entity_id,1,instr(NEW.entity_id,':')-1) AND source_message_id=CAST(substr(NEW.entity_id,instr(NEW.entity_id,':')+1) AS INTEGER)); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT NEW.media_id WHERE NEW.media_id IS NOT NULL UNION SELECT id FROM media WHERE NEW.entity_type='telegram_video' AND instr(NEW.entity_id,':')>0 AND source_channel=substr(NEW.entity_id,1,instr(NEW.entity_id,':')-1) AND source_message_id=CAST(substr(NEW.entity_id,instr(NEW.entity_id,':')+1) AS INTEGER)); END;

