CREATE TRIGGER ax_lr_media_insert AFTER INSERT ON media BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT NEW.id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT NEW.id); END;

CREATE TRIGGER ax_lr_media_update AFTER UPDATE OF status, streamable, source_channel, source_message_id ON media BEGIN DELETE FROM ax_library_ready WHERE media_id IN (SELECT NEW.id); INSERT OR IGNORE INTO ax_library_ready(media_id) SELECT id FROM archive_x_library_media_exact WHERE id IN (SELECT NEW.id); END;

CREATE TRIGGER ax_lr_media_delete AFTER DELETE ON media BEGIN DELETE FROM ax_library_ready WHERE media_id=OLD.id; END;

CREATE VIEW archive_x_library_media AS
            SELECT cm.*
            FROM archive_x_catalogued_media cm
            JOIN ax_library_ready lr ON lr.media_id=cm.id;

