CREATE TABLE telegram_document_registry (
            registry_key TEXT PRIMARY KEY,
            document_id TEXT,
            identity_kind TEXT NOT NULL DEFAULT 'LEGACY_MESSAGE',
            access_hash TEXT,
            filename TEXT,
            size_bytes INTEGER NOT NULL DEFAULT 0,
            duration REAL NOT NULL DEFAULT 0,
            width INTEGER NOT NULL DEFAULT 0,
            height INTEGER NOT NULL DEFAULT 0,
            mime_type TEXT,
            caption TEXT,
            message_date TEXT,
            grouped_id TEXT,
            companion_message_ids_json TEXT NOT NULL DEFAULT '[]',
            known_state TEXT NOT NULL DEFAULT 'KNOWN',
            prepared_state TEXT NOT NULL DEFAULT 'PENDING',
            prepared_at TEXT,
            prepared_json TEXT NOT NULL DEFAULT '{}',
            oshash TEXT,
            phash TEXT,
            media_id INTEGER,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );

CREATE UNIQUE INDEX idx_telegram_registry_document_id
            ON telegram_document_registry(document_id) WHERE document_id IS NOT NULL AND document_id<>'';

CREATE INDEX idx_telegram_registry_prepared ON telegram_document_registry(prepared_state,updated_at);

CREATE INDEX idx_telegram_registry_oshash ON telegram_document_registry(oshash) WHERE oshash IS NOT NULL AND oshash<>'';

CREATE TABLE telegram_document_locations (
            channel_id TEXT NOT NULL,
            message_id INTEGER NOT NULL,
            registry_key TEXT NOT NULL,
            access_hash TEXT,
            file_reference_b64 TEXT,
            thumbnail_message_id INTEGER,
            message_date TEXT,
            caption TEXT,
            location_state TEXT NOT NULL DEFAULT 'PRESENT',
            last_seen_at TEXT NOT NULL,
            PRIMARY KEY(channel_id,message_id)
        );

CREATE INDEX idx_telegram_locations_registry ON telegram_document_locations(registry_key,location_state);

CREATE INDEX idx_telegram_locations_channel ON telegram_document_locations(channel_id,location_state,message_id);

CREATE TABLE telegram_move_cleanup (
            source_channel TEXT NOT NULL,
            source_message_id INTEGER NOT NULL,
            destination_channel TEXT NOT NULL,
            destination_message_id INTEGER NOT NULL,
            document_id TEXT,
            retry_count INTEGER NOT NULL DEFAULT 0,
            last_error TEXT,
            next_attempt_at TEXT,
            status TEXT NOT NULL DEFAULT 'PENDING',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY(source_channel,source_message_id)
        );

CREATE INDEX idx_telegram_move_cleanup_due ON telegram_move_cleanup(status,next_attempt_at);

CREATE TABLE telegram_channel_registry_state (
            channel_id TEXT PRIMARY KEY,
            high_water_mark INTEGER NOT NULL DEFAULT 0,
            last_scan_at TEXT,
            last_scan_status TEXT NOT NULL DEFAULT 'NEVER',
            last_scan_detail TEXT NOT NULL DEFAULT '{}',
            updated_at TEXT NOT NULL
        );

CREATE INDEX idx_jobs_admission ON jobs(status, admission_state, priority, next_run_at, created_at);

CREATE INDEX idx_jobs_admission_reason ON jobs(admission_state, admission_reason, updated_at);

CREATE INDEX idx_jobs_execution_lease ON jobs(lease_expires_at, worker_state);

CREATE INDEX idx_jobs_retry ON jobs(status, next_run_at, retry_count, priority, created_at);

CREATE INDEX idx_jobs_deadline ON jobs(status, deadline_at, priority, created_at);

CREATE TABLE execution_lane_slots (
            slot_id TEXT PRIMARY KEY, lane_id TEXT NOT NULL, job_id TEXT NOT NULL,
            execution_id TEXT, lease_id TEXT, state TEXT NOT NULL DEFAULT 'ACTIVE',
            acquired_at TEXT NOT NULL, expires_at TEXT, last_heartbeat TEXT NOT NULL,
            FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE
        );

CREATE INDEX idx_lane_slots_lane_state ON execution_lane_slots(lane_id,state);

CREATE INDEX idx_lane_slots_execution ON execution_lane_slots(execution_id,state);

CREATE INDEX idx_lane_slots_expiry ON execution_lane_slots(expires_at,state);

CREATE TABLE resource_leases (
            resource_key TEXT PRIMARY KEY,
            job_id TEXT,
            owner_launch_id TEXT NOT NULL,
            acquired_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            lease_id TEXT,
            execution_id TEXT,
            resource_class TEXT NOT NULL DEFAULT 'BACKGROUND',
            resource_type TEXT NOT NULL DEFAULT 'GENERIC',
            reserved_amount REAL NOT NULL DEFAULT 1,
            actual_amount REAL NOT NULL DEFAULT 0,
            created_at TEXT,
            expires_at TEXT,
            last_heartbeat TEXT,
            state TEXT NOT NULL DEFAULT 'RESERVED'
        );

CREATE UNIQUE INDEX idx_resource_leases_lease_id ON resource_leases(lease_id) WHERE lease_id IS NOT NULL;

CREATE INDEX idx_resource_leases_execution ON resource_leases(execution_id, state);

CREATE INDEX idx_resource_leases_expiry ON resource_leases(expires_at, state);

CREATE INDEX idx_resource_leases_job_state ON resource_leases(job_id, state);

CREATE UNIQUE INDEX idx_job_journal_event_id ON job_journal(event_id) WHERE event_id IS NOT NULL;

CREATE TABLE archive_x_deliveries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            source_kind TEXT NOT NULL DEFAULT 'unknown',
            source_channel TEXT NOT NULL DEFAULT '',
            source_message_id INTEGER NOT NULL DEFAULT 0,
            source_media_id INTEGER,
            destination_channel TEXT NOT NULL,
            destination_video_message_id INTEGER NOT NULL,
            destination_thumbnail_message_id INTEGER NOT NULL DEFAULT 0,
            identity_key TEXT NOT NULL DEFAULT '',
            filename TEXT NOT NULL DEFAULT '',
            file_size INTEGER NOT NULL DEFAULT 0,
            duration REAL NOT NULL DEFAULT 0,
            width INTEGER NOT NULL DEFAULT 0,
            height INTEGER NOT NULL DEFAULT 0,
            fps REAL NOT NULL DEFAULT 0,
            bitrate INTEGER NOT NULL DEFAULT 0,
            codec TEXT NOT NULL DEFAULT '',
            audio_codec TEXT NOT NULL DEFAULT '',
            caption TEXT NOT NULL DEFAULT '',
            action TEXT NOT NULL DEFAULT 'TRANSFER',
            status TEXT NOT NULL DEFAULT 'VERIFIED',
            verified_at TEXT NOT NULL,
            library_media_id INTEGER,
            error TEXT NOT NULL DEFAULT '',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE(destination_channel, destination_video_message_id)
        );

CREATE INDEX idx_ax_deliveries_source ON archive_x_deliveries(source_channel, source_message_id);

CREATE INDEX idx_ax_deliveries_identity ON archive_x_deliveries(identity_key);

CREATE INDEX idx_ax_deliveries_verified ON archive_x_deliveries(status, verified_at DESC);

CREATE INDEX idx_media_upload_date_id ON media(upload_date DESC, id DESC);

CREATE INDEX idx_media_source_channel_date ON media(source_channel, upload_date DESC, id DESC);

CREATE INDEX idx_media_favorite_upload_date_id ON media(favorite, upload_date DESC, id DESC);

CREATE INDEX idx_media_resolution_upload_date_id ON media(resolution_category, upload_date DESC, id DESC);

CREATE INDEX idx_media_size_id ON media(size DESC, id DESC);

CREATE INDEX idx_media_duration_id ON media(duration DESC, id DESC);

CREATE INDEX idx_media_filename_nocase ON media(filename COLLATE NOCASE, id);

CREATE INDEX idx_media_height_upload_date_id ON media(height, upload_date DESC, id DESC);

CREATE INDEX idx_media_effective_date_id ON media(COALESCE(NULLIF(upload_date,''),created_at) DESC, id DESC);

CREATE INDEX idx_media_source_effective_date_id ON media(source_channel, COALESCE(NULLIF(upload_date,''),created_at) DESC, id DESC);

CREATE INDEX idx_watch_history_last_played ON watch_history(last_played_at DESC, media_id);

CREATE INDEX idx_watch_history_completed ON watch_history(completed, last_played_at DESC);

CREATE INDEX idx_entity_favorites_type_created ON entity_favorites(entity_type, created_at DESC, entity_id);

CREATE INDEX idx_jobs_status_updated ON jobs(status, updated_at DESC, created_at DESC);

CREATE INDEX idx_events_created_id ON events(created_at DESC, id DESC);

CREATE INDEX idx_provider_sync_updated ON provider_sync_state(provider, updated_at DESC);

CREATE TRIGGER ax_placeholder_video_performers_insert AFTER INSERT ON video_performers WHEN NEW.performer_id NOT IN (SELECT id FROM performers WHERE lower(trim(name))='unknown performer') BEGIN DELETE FROM video_performers WHERE video_id=NEW.video_id AND performer_id IN (SELECT id FROM performers WHERE lower(trim(name))='unknown performer'); DELETE FROM local_video_performers WHERE video_id=NEW.video_id AND performer_id IN (SELECT id FROM performers WHERE lower(trim(name))='unknown performer'); END;

CREATE TRIGGER ax_placeholder_local_video_performers_insert AFTER INSERT ON local_video_performers WHEN NEW.performer_id NOT IN (SELECT id FROM performers WHERE lower(trim(name))='unknown performer') BEGIN DELETE FROM video_performers WHERE video_id=NEW.video_id AND performer_id IN (SELECT id FROM performers WHERE lower(trim(name))='unknown performer'); DELETE FROM local_video_performers WHERE video_id=NEW.video_id AND performer_id IN (SELECT id FROM performers WHERE lower(trim(name))='unknown performer'); END;

CREATE TRIGGER ax_placeholder_video_studios_insert AFTER INSERT ON video_studios WHEN NEW.studio_id NOT IN (SELECT id FROM studios WHERE lower(trim(name))='unknown studio') BEGIN DELETE FROM video_studios WHERE video_id=NEW.video_id AND studio_id IN (SELECT id FROM studios WHERE lower(trim(name))='unknown studio'); END;

CREATE TABLE web_sessions ( token_hash TEXT PRIMARY KEY, username TEXT NOT NULL, expires REAL NOT NULL);

